-- =============================================================================
-- Expand question bank: +50 per section (AUD, FAR, REG)
-- Brings totals from ~30 to ~80 per section
-- =============================================================================

-- =============================================================================
-- AUD — Auditing and Attestation (section_id = 1)
-- 50 questions: 13 easy, 24 medium, 13 hard
-- =============================================================================
insert into questions (section_id, topic, stem, choices, correct_index, explanation, difficulty) values

-- Ethics and Independence (5 questions)
(1, 'Ethics and Independence',
 'Which of the following threats to independence arises when an auditor provides a service that involves making judgments that will be subject to audit procedures?',
 '["Advocacy threat", "Self-review threat", "Self-interest threat", "Intimidation threat"]'::jsonb,
 1,
 'A self-review threat occurs when the auditor audits their own work product or judgments. For example, preparing financial statements and then auditing them creates a self-review threat because the auditor may be reluctant to identify errors in their own work.',
 'medium'),

(1, 'Ethics and Independence',
 'Under the AICPA Code of Professional Conduct, a CPA in public practice must maintain independence when performing which of the following services?',
 '["Tax return preparation", "Management consulting", "Attest engagements", "Personal financial planning"]'::jsonb,
 2,
 'Independence is required for attest engagements, which include audits, reviews, and other attestation services. Tax preparation, consulting, and financial planning are nonattest services that do not require independence, though objectivity is always required under the code.',
 'easy'),

(1, 'Ethics and Independence',
 'A CPA discovers that a close friend has been appointed to the board of directors of an audit client. Under the conceptual framework, what should the CPA do first?',
 '["Immediately resign from the engagement", "Evaluate the significance of the threat and determine if safeguards can reduce it to an acceptable level", "Ignore the relationship since it is not a family relationship", "Disclose the relationship only if asked by the audit committee"]'::jsonb,
 1,
 'The conceptual framework approach requires the CPA to first identify and evaluate the significance of the threat to independence. If the threat is not at an acceptable level, the CPA must determine whether safeguards can reduce it. Immediate resignation may be premature, and ignoring the relationship would violate professional standards.',
 'medium'),

(1, 'Ethics and Independence',
 'Which of the following is an example of an intimidation threat to auditor independence?',
 '["The audit firm earns 40% of its revenue from one client", "The engagement partner has served the client for 15 consecutive years", "The client threatens to replace the auditor if an unfavorable opinion is issued", "The auditor holds stock in the client"]'::jsonb,
 2,
 'An intimidation threat exists when the auditor may be deterred from acting objectively due to actual or perceived pressure from the client. A threat to replace the auditor over an unfavorable opinion is a classic intimidation threat. Revenue concentration is a self-interest threat, long tenure creates a familiarity threat, and stock ownership is a financial interest threat.',
 'medium'),

(1, 'Ethics and Independence',
 'The AICPA requires a cooling-off period before a partner on an attest engagement can accept employment with the client. What is the primary purpose of this requirement?',
 '["To prevent the partner from sharing confidential audit information", "To mitigate familiarity and self-interest threats to the firm''s continuing independence", "To ensure the partner has time to transition audit work", "To comply with SEC insider trading rules"]'::jsonb,
 1,
 'The cooling-off period mitigates threats to the firm''s independence that arise when a former partner joins the client. The familiarity threat (existing relationships with audit team) and self-interest threat (desire to maintain the relationship) could compromise the remaining team''s objectivity in future audits.',
 'hard'),

-- Audit Planning (5 questions)
(1, 'Audit Planning',
 'Which of the following is the auditor required to do as part of preliminary engagement activities?',
 '["Determine the audit fee", "Evaluate compliance with ethical requirements, including independence", "Select the sample sizes for substantive testing", "Draft the audit report"]'::jsonb,
 1,
 'Preliminary engagement activities include evaluating compliance with ethical requirements (including independence), determining whether to accept or continue the client relationship, and establishing the terms of the engagement. Audit fees, sample sizes, and report drafting are addressed later in the engagement.',
 'easy'),

(1, 'Audit Planning',
 'An auditor discovers that the predecessor auditor''s workpapers contain a going concern qualification. How should this affect the current auditor''s planning?',
 '["It has no effect since each audit stands on its own", "The auditor should plan additional procedures to evaluate the entity''s ability to continue as a going concern", "The auditor should automatically issue a going concern opinion", "The auditor should decline the engagement"]'::jsonb,
 1,
 'A prior going concern qualification is a significant planning consideration. The current auditor should assess whether the conditions that led to the previous qualification still exist and plan procedures to evaluate the entity''s current ability to continue as a going concern. Each audit requires independent evaluation, but prior findings inform planning.',
 'medium'),

(1, 'Audit Planning',
 'The engagement letter for an audit should include which of the following?',
 '["The expected audit opinion", "The objective and scope of the audit", "A guarantee that fraud will be detected", "The audit fee only"]'::jsonb,
 1,
 'The engagement letter establishes the terms of the engagement and should include the objective and scope of the audit, management''s responsibilities, the auditor''s responsibilities, the applicable financial reporting framework, and the expected form of reports. It should not guarantee fraud detection or specify the expected opinion.',
 'easy'),

(1, 'Audit Planning',
 'When using the work of a specialist, which of the following is the auditor''s responsibility?',
 '["To possess the same expertise as the specialist", "To evaluate the adequacy and reasonableness of the specialist''s findings for the auditor''s purposes", "To assume full responsibility for the specialist''s conclusions", "To disclose the specialist''s name in the audit report"]'::jsonb,
 1,
 'The auditor must evaluate whether the specialist''s findings are adequate for audit purposes, including assessing the specialist''s competence, capabilities, and objectivity. The auditor need not have the same expertise but must understand the work enough to evaluate it. The specialist is not mentioned in the report unless it modifies the opinion.',
 'medium'),

(1, 'Audit Planning',
 'During planning, the auditor considers the risk of material misstatement due to fraud. Which of the following is always presumed to be a significant risk of fraud?',
 '["Inventory valuation", "Revenue recognition", "Fixed asset impairment", "Accounts payable completeness"]'::jsonb,
 1,
 'AU-C 240 requires the auditor to presume that there are risks of fraud in revenue recognition and to evaluate which types of revenue, transactions, or assertions give rise to fraud risks. This presumption can be overcome only in rare circumstances with documented justification. No such blanket presumption exists for inventory, fixed assets, or accounts payable.',
 'medium'),

-- Risk Assessment (5 questions)
(1, 'Risk Assessment',
 'What is the relationship between detection risk and the risk of material misstatement?',
 '["They move in the same direction — as one increases, the other increases", "They have an inverse relationship — as the risk of material misstatement increases, the acceptable level of detection risk decreases", "They are unrelated concepts", "Detection risk is always higher than the risk of material misstatement"]'::jsonb,
 1,
 'Detection risk and the risk of material misstatement have an inverse relationship within the audit risk model (AR = RMM x DR). When the assessed risk of material misstatement increases, the auditor must decrease detection risk by performing more effective or extensive audit procedures to maintain audit risk at an acceptably low level.',
 'medium'),

(1, 'Risk Assessment',
 'Which of the following is an example of an inherent risk factor?',
 '["Lack of segregation of duties in the accounting department", "Management''s failure to review bank reconciliations", "Complex calculations required for pension obligations", "Absence of an internal audit function"]'::jsonb,
 2,
 'Inherent risk relates to the susceptibility of an assertion to misstatement before considering internal controls. Complex calculations, such as those required for pension obligations, increase inherent risk because of the difficulty involved. The other options relate to control risk factors — deficiencies in the design or operation of internal controls.',
 'easy'),

(1, 'Risk Assessment',
 'An auditor determines that a client''s industry is experiencing significant regulatory changes. This primarily affects which component of audit risk?',
 '["Detection risk", "Control risk", "Inherent risk", "Sampling risk"]'::jsonb,
 2,
 'Significant regulatory changes increase inherent risk at the financial statement level because new requirements may lead to errors in compliance, new accounting treatments, or financial statement misstatements. Inherent risk exists independent of internal controls and reflects the nature of the entity and its environment.',
 'easy'),

(1, 'Risk Assessment',
 'Which of the following audit procedures would an auditor most likely perform to identify risks of material misstatement?',
 '["Confirming accounts receivable balances with customers", "Inquiring of management about business risks and performing analytical procedures on interim financial data", "Recalculating depreciation expense for all fixed assets", "Counting inventory on hand at the client''s warehouse"]'::jsonb,
 1,
 'Risk assessment procedures include inquiry of management and others, analytical procedures, and observation and inspection. These procedures help the auditor understand the entity, its environment, and internal controls to identify risks of material misstatement. Confirmations, recalculations, and inventory counts are substantive procedures performed in response to assessed risks.',
 'medium'),

(1, 'Risk Assessment',
 'When assessing the risk of material misstatement at the assertion level, the auditor should consider which of the following?',
 '["The auditor''s level of experience with the client", "The nature of the account, the complexity of transactions, and the susceptibility to fraud", "The size of the audit firm relative to the client", "The number of hours budgeted for the engagement"]'::jsonb,
 1,
 'Assertion-level risk assessment considers factors specific to classes of transactions, account balances, and disclosures, including the nature of the account, transaction complexity, volume, susceptibility to fraud, and related controls. Auditor experience, firm size, and budget hours are not relevant to assessing the client''s risk of misstatement.',
 'hard'),

-- Internal Controls (5 questions)
(1, 'Internal Controls',
 'Which component of the COSO internal control framework deals with the entity''s process for identifying and responding to business risks?',
 '["Control environment", "Risk assessment", "Control activities", "Information and communication"]'::jsonb,
 1,
 'The risk assessment component involves the entity''s process for identifying, analyzing, and managing risks relevant to the preparation of financial statements. This includes risks from changes in the operating environment, new personnel, rapid growth, new technology, and new accounting pronouncements.',
 'easy'),

(1, 'Internal Controls',
 'An auditor is evaluating the control environment of a new audit client. Which of the following would be the strongest indicator of a weak control environment?',
 '["Management frequently overrides established controls to expedite transactions", "The company uses an older accounting software system", "The company has a small accounting staff", "The company operates in a competitive industry"]'::jsonb,
 0,
 'Management override of controls is one of the strongest indicators of a weak control environment. It suggests a tone at the top that does not prioritize integrity and ethical values, which are foundational to the control environment. Old software, small staff, and competitive industries may present risks but do not inherently indicate a weak control environment.',
 'medium'),

(1, 'Internal Controls',
 'What is the purpose of a walkthrough in the audit of internal controls?',
 '["To test the operating effectiveness of controls", "To confirm the auditor''s understanding of the design and implementation of controls by tracing a transaction through the system", "To count physical inventory", "To determine the audit fee"]'::jsonb,
 1,
 'A walkthrough involves tracing a transaction from origination through processing to recording in the financial statements. Its purpose is to confirm the auditor''s understanding of the control design and whether controls have been implemented (placed in operation). Walkthroughs alone do not provide sufficient evidence of operating effectiveness.',
 'medium'),

(1, 'Internal Controls',
 'Which of the following is an example of a preventive control rather than a detective control?',
 '["Monthly bank reconciliation", "Exception reports reviewed by management", "Required supervisory approval before processing a disbursement", "Variance analysis of budgeted versus actual expenses"]'::jsonb,
 2,
 'Preventive controls are designed to prevent errors or fraud from occurring in the first place. Requiring supervisory approval before processing is a preventive control because it stops unauthorized transactions before they happen. Bank reconciliations, exception reports, and variance analyses are detective controls that identify issues after they have occurred.',
 'easy'),

(1, 'Internal Controls',
 'An auditor is testing IT general controls. Which of the following would be classified as an IT general control?',
 '["An automated three-way match of purchase orders, receiving reports, and vendor invoices", "Password requirements and user access management", "An automated calculation of depreciation expense", "An edit check that rejects invalid customer numbers"]'::jsonb,
 1,
 'IT general controls (ITGCs) are policies and procedures that relate to many applications and support the effective functioning of application controls. Password requirements and user access management are ITGCs because they control who can access and modify data across systems. The other options are application controls that operate within specific processes.',
 'medium'),

-- Audit Evidence (5 questions)
(1, 'Audit Evidence',
 'Which assertion is the auditor primarily testing when confirming accounts receivable with customers?',
 '["Completeness", "Existence and accuracy", "Classification", "Presentation"]'::jsonb,
 1,
 'Accounts receivable confirmations primarily test the existence assertion (do the receivables actually exist?) and accuracy (are the amounts correct?). Confirmations are sent to recorded customers to verify the recorded balances. To test completeness (unrecorded receivables), the auditor would need to use a different direction of testing, such as tracing from shipping documents to the receivables ledger.',
 'easy'),

(1, 'Audit Evidence',
 'An auditor is testing the valuation assertion for inventory. Which of the following procedures would be most appropriate?',
 '["Observing the physical inventory count", "Comparing inventory costs to current market prices and assessing the lower of cost or net realizable value", "Sending confirmations to suppliers", "Tracing inventory purchases to the general ledger"]'::jsonb,
 1,
 'Valuation testing for inventory focuses on whether inventory is properly valued at the lower of cost or net realizable value. Comparing recorded costs to current market prices and assessing NRV tests this assertion directly. Physical observation tests existence, confirmations test accounts payable, and tracing to the ledger tests completeness or accuracy of recording.',
 'medium'),

(1, 'Audit Evidence',
 'Which of the following is the least reliable form of audit evidence?',
 '["A bank confirmation received directly from the bank", "A purchase invoice obtained from the client''s files", "An oral representation from the client''s CEO", "A canceled check examined by the auditor"]'::jsonb,
 2,
 'Oral representations from management are the least reliable form of evidence because they are not documented and come from an interested party. Evidence reliability increases when it is written, obtained from external independent sources, and obtained directly by the auditor. Bank confirmations are the most reliable of these options, followed by the canceled check and the internal invoice.',
 'easy'),

(1, 'Audit Evidence',
 'An auditor obtains a management representation letter at the conclusion of an audit. This letter is intended to:',
 '["Replace the need for other audit evidence", "Confirm management''s responsibility for the financial statements and document specific representations made during the audit", "Serve as the primary basis for the audit opinion", "Guarantee the accuracy of the financial statements"]'::jsonb,
 1,
 'The management representation letter confirms management''s responsibility for the financial statements and formalizes oral representations made during the audit. It is required but does not replace other audit evidence — it complements it. The letter is not a guarantee and should not be the sole or primary basis for audit conclusions.',
 'medium'),

(1, 'Audit Evidence',
 'When testing the accuracy of a client''s depreciation calculation, the auditor recalculates the expense using the stated method, useful life, and residual value. This procedure is an example of:',
 '["Inspection", "Observation", "Recalculation", "Inquiry"]'::jsonb,
 2,
 'Recalculation involves the auditor independently verifying mathematical accuracy by reperforming calculations. Checking depreciation computations is a classic example. Inspection involves examining records or documents, observation involves watching a process, and inquiry involves seeking information from knowledgeable persons.',
 'easy'),

-- Audit Sampling (4 questions)
(1, 'Audit Sampling',
 'What is the primary difference between statistical and nonstatistical sampling?',
 '["Statistical sampling is always more effective than nonstatistical sampling", "Statistical sampling uses random selection and probability theory to evaluate results, while nonstatistical sampling relies on auditor judgment", "Nonstatistical sampling requires larger sample sizes", "Statistical sampling can only be used for tests of controls"]'::jsonb,
 1,
 'The key difference is that statistical sampling uses mathematical probability theory to determine sample sizes and evaluate results, requiring random selection. Nonstatistical sampling relies on auditor judgment for both. Both methods can provide sufficient appropriate evidence when properly applied, and neither is inherently superior.',
 'medium'),

(1, 'Audit Sampling',
 'In attribute sampling for tests of controls, what does the tolerable rate of deviation represent?',
 '["The actual rate of deviations found in the sample", "The maximum rate of control deviations the auditor is willing to accept and still rely on the control", "The expected rate of deviations in the population", "The probability of the sample results being incorrect"]'::jsonb,
 1,
 'The tolerable rate is the maximum deviation rate from a prescribed control that the auditor is willing to accept without modifying the planned reliance on the control. It is set during planning based on the planned degree of reliance on the control and represents the auditor''s threshold for acceptable control performance.',
 'medium'),

(1, 'Audit Sampling',
 'An auditor uses systematic selection to obtain a sample of sales invoices. Which of the following conditions could make systematic selection unreliable?',
 '["The population is too large", "The population is arranged in a random order", "There is a pattern in the population that coincides with the sampling interval", "The sample size is too small"]'::jsonb,
 2,
 'Systematic selection can produce a biased sample if the population has a pattern (such as cyclical entries) that coincides with the sampling interval. For example, if every 10th invoice is a month-end adjusting entry and the sampling interval is 10, the sample would either always include or always exclude these entries, misrepresenting the population.',
 'hard'),

(1, 'Audit Sampling',
 'In a variables sampling plan for a substantive test of an account balance, the auditor determines that the projected misstatement exceeds tolerable misstatement. What should the auditor conclude?',
 '["The account balance is fairly stated", "The sample results do not support the recorded amount, and additional procedures or a larger sample may be needed", "The account must be written down by the projected misstatement", "The auditor should issue a qualified opinion"]'::jsonb,
 1,
 'When projected misstatement exceeds tolerable misstatement, the auditor cannot conclude that the account balance is not materially misstated. The auditor should consider expanding the sample, performing additional procedures, or requesting management to investigate and adjust the balance. The audit opinion decision comes later after evaluating all evidence.',
 'hard'),

-- Substantive Procedures (4 questions)
(1, 'Substantive Procedures',
 'An auditor is testing the existence assertion for equipment. Which of the following procedures is most appropriate?',
 '["Reviewing depreciation calculations", "Physically inspecting a sample of equipment items listed in the fixed asset register", "Reviewing purchase orders for new equipment", "Examining the insurance policy for equipment coverage"]'::jsonb,
 1,
 'Testing existence requires verifying that recorded assets actually exist. Physically inspecting equipment listed in the register confirms that the assets are present. This tests in the direction from records to physical assets. Depreciation calculations test valuation, purchase orders may support occurrence, and insurance policies provide indirect evidence.',
 'easy'),

(1, 'Substantive Procedures',
 'An auditor performs a cutoff test for sales near year-end. What is the primary objective of this procedure?',
 '["To verify that sales are recorded at the correct amounts", "To ensure that sales transactions are recorded in the correct accounting period", "To verify that all sales have been recorded", "To determine whether sales discounts were properly authorized"]'::jsonb,
 1,
 'Cutoff testing ensures that transactions are recorded in the proper period. For sales, this means verifying that revenue from goods shipped or services rendered before year-end is recorded in the current period, and revenue from transactions after year-end is recorded in the subsequent period. This addresses the cutoff assertion.',
 'medium'),

(1, 'Substantive Procedures',
 'When performing analytical procedures as a substantive test, the auditor develops an expectation of an account balance and compares it to the recorded amount. If the difference exceeds the threshold, the auditor should:',
 '["Immediately inform management of the error", "Investigate the difference by performing additional procedures to determine whether a misstatement exists", "Adjust the financial statements for the difference", "Conclude that the financial statements are materially misstated"]'::jsonb,
 1,
 'When analytical procedures reveal an unexpected difference, the auditor investigates by inquiring of management and performing additional procedures. The difference may have a plausible explanation or may indicate a misstatement. The auditor should not assume it is an error or automatically adjust without further investigation.',
 'medium'),

(1, 'Substantive Procedures',
 'To test the completeness of accounts payable, an auditor would most effectively:',
 '["Send confirmations to vendors with large recorded balances", "Examine disbursements recorded after year-end and trace them to the accounts payable listing at year-end", "Vouch recorded payables to receiving reports", "Review the aged accounts payable trial balance"]'::jsonb,
 1,
 'Completeness testing searches for unrecorded items. Examining cash disbursements after year-end identifies payments for obligations that existed at year-end but may not have been recorded as payables. Confirming existing balances tests recorded amounts, vouching recorded items tests existence, and the trial balance only shows what is already recorded.',
 'hard'),

-- Audit Reports (5 questions)
(1, 'Audit Reports',
 'An auditor issues a qualified opinion. Which of the following phrases is included in the opinion paragraph?',
 '["The financial statements present fairly, in all material respects", "Except for the effects of the matter described, the financial statements present fairly, in all material respects", "The financial statements do not present fairly", "We do not express an opinion on the financial statements"]'::jsonb,
 1,
 'A qualified opinion uses the phrase "except for" to identify the specific area of disagreement or limitation while still providing an opinion on the rest of the financial statements. An unmodified opinion says statements "present fairly," an adverse opinion says they "do not present fairly," and a disclaimer says "we do not express an opinion."',
 'easy'),

(1, 'Audit Reports',
 'When would an auditor issue a disclaimer of opinion?',
 '["When there is a material misstatement in the financial statements", "When the auditor is unable to obtain sufficient appropriate audit evidence and the possible effects are pervasive", "When the financial statements depart from GAAP in an immaterial way", "When the client changes accounting methods"]'::jsonb,
 1,
 'A disclaimer of opinion is issued when the auditor is unable to obtain sufficient appropriate audit evidence to form an opinion and the potential effects of undetected misstatements could be both material and pervasive. Material misstatements lead to qualified or adverse opinions. Immaterial departures do not affect the opinion, and accounting changes may require an emphasis paragraph.',
 'medium'),

(1, 'Audit Reports',
 'An emphasis-of-matter paragraph in an audit report is used to draw attention to a matter appropriately presented in the financial statements. Which of the following might warrant an emphasis-of-matter paragraph?',
 '["An uncorrected misstatement", "Significant going concern uncertainty disclosed in the notes", "A disagreement with management about an accounting policy", "A scope limitation imposed by management"]'::jsonb,
 1,
 'An emphasis-of-matter paragraph highlights matters already properly presented or disclosed in the financial statements that the auditor believes are fundamental to users'' understanding. Going concern uncertainty, significant related-party transactions, and major catastrophes are common examples. Uncorrected misstatements and scope limitations affect the opinion itself.',
 'medium'),

(1, 'Audit Reports',
 'Which of the following is required in the auditor''s report under AU-C 700?',
 '["A description of each audit procedure performed", "The auditor''s opinion on the effectiveness of internal controls", "A statement that the auditor is responsible for expressing an opinion based on the audit", "A list of all adjusting entries proposed during the audit"]'::jsonb,
 2,
 'The auditor''s report must include a statement of the auditor''s responsibility to express an opinion on the financial statements based on the audit. It does not detail every procedure performed, does not opine on internal controls (unless it is an integrated audit), and does not disclose proposed adjustments.',
 'easy'),

(1, 'Audit Reports',
 'A group engagement partner relies on a component auditor to audit a significant subsidiary. If the group engagement partner decides not to make reference to the component auditor, the group engagement partner must:',
 '["Include an other-matter paragraph naming the component auditor", "Assume full responsibility for the work of the component auditor and evaluate the sufficiency and appropriateness of that work", "Resign from the engagement", "Issue a qualified opinion due to the use of another auditor"]'::jsonb,
 1,
 'When the group engagement partner decides not to make reference to the component auditor in the report, the group partner assumes responsibility for the component auditor''s work. This requires evaluating the component auditor''s independence, professional competence, and the sufficiency and appropriateness of the audit evidence obtained.',
 'hard'),

-- Review/Compilation Engagements (4 questions)
(1, 'Review/Compilation Engagements',
 'A compilation report must include which of the following statements?',
 '["The accountant obtained reasonable assurance that the financial statements are free of material misstatement", "The accountant did not audit or review the financial statements and accordingly does not express an opinion or provide any assurance", "The financial statements are presented fairly in all material respects", "Management is solely responsible for detecting fraud"]'::jsonb,
 1,
 'The standard compilation report states that the accountant did not audit or review the financial statements and therefore does not express an opinion or provide any assurance on them. A compilation involves presenting financial statements based on management''s representations without performing verification procedures.',
 'easy'),

(1, 'Review/Compilation Engagements',
 'During a review engagement, the accountant notices that depreciation expense appears unusually low compared to the prior year and the entity''s asset base. What should the accountant do?',
 '["Ignore it because reviews do not require the accountant to investigate anomalies", "Make inquiries of management about the change and consider whether additional procedures are needed", "Issue a qualified review report", "Withdraw from the engagement"]'::jsonb,
 1,
 'In a review engagement, the accountant uses inquiry and analytical procedures to obtain limited assurance. When analytical procedures reveal unusual items, the accountant should inquire of management to understand the reason and determine whether the matter has been properly accounted for. Further inquiry or additional procedures may be necessary.',
 'medium'),

(1, 'Review/Compilation Engagements',
 'For a preparation engagement under SSARS, is the accountant required to be independent of the entity?',
 '["Yes, independence is always required", "No, independence is not required but a lack of independence must be disclosed", "No, independence is not required and no disclosure is needed", "Independence is required only if the statements will be used by third parties"]'::jsonb,
 2,
 'In a preparation engagement, the accountant is not required to be independent and is not required to disclose a lack of independence. This is the lowest level of service under SSARS. For compilations, independence is also not required but must be disclosed if lacking. For reviews, independence is required.',
 'medium'),

(1, 'Review/Compilation Engagements',
 'Which of the following best describes the difference between an engagement to prepare financial statements and a compilation engagement?',
 '["There is no difference; they are the same service", "A preparation engagement does not require a report to be issued, while a compilation requires a report", "A compilation does not require understanding the client''s business", "A preparation engagement provides limited assurance"]'::jsonb,
 1,
 'The key difference is the reporting requirement. In a preparation engagement, no report is required (though each page must include a legend stating no assurance is provided). A compilation requires the accountant to issue a report. Both require an understanding of the client''s business, and neither provides assurance.',
 'hard'),

-- Attestation Engagements (3 questions)
(1, 'Attestation Engagements',
 'Under SSAE No. 18, which of the following types of attestation engagements provides the lowest level of assurance?',
 '["Examination engagement", "Review engagement", "Agreed-upon procedures engagement", "All provide the same level of assurance"]'::jsonb,
 2,
 'An agreed-upon procedures (AUP) engagement does not provide an opinion or assurance conclusion. The practitioner merely reports factual findings from performing specific procedures. An examination provides positive (reasonable) assurance, and a review provides negative (limited) assurance. AUPs provide no assurance at all.',
 'medium'),

(1, 'Attestation Engagements',
 'A company hires a CPA to examine its compliance with privacy regulations. The CPA must:',
 '["Follow GAAS for financial statement audits", "Follow SSAE standards, obtain sufficient evidence, and issue an opinion on compliance", "Only perform agreed-upon procedures", "Provide a compilation of the compliance information"]'::jsonb,
 1,
 'An examination of compliance is an attestation engagement governed by SSAE standards. The CPA obtains sufficient appropriate evidence to provide a reasonable basis for expressing an opinion on whether the entity complied, in all material respects, with the specified requirements. This follows the attestation standards, not GAAS for financial statement audits.',
 'medium'),

(1, 'Attestation Engagements',
 'In a review-level attestation engagement on prospective financial statements, the practitioner''s report should include:',
 '["A positive opinion that the assumptions are reasonable", "A statement that the practitioner is not aware of any material modifications needed for the presentation to be in conformity with guidelines", "A disclaimer that the prospective results may not be achieved", "Both a negative assurance conclusion and a caveat that prospective results may not be achieved"]'::jsonb,
 3,
 'For review-level attestation on prospective financial statements, the report includes both negative assurance (nothing came to the practitioner''s attention indicating the assumptions are not reasonable) and a required caveat that prospective results may not be achieved. This dual element is unique to prospective financial statement engagements.',
 'hard'),

-- Quality Management (4 questions)
(1, 'Quality Management',
 'Which of the following is a responsibility of the engagement partner under quality management standards?',
 '["Setting the firm''s overall quality management policies", "Taking overall responsibility for managing and achieving quality on the audit engagement", "Approving the firm''s human resources policies", "Conducting firm-wide inspections of completed engagements"]'::jsonb,
 1,
 'The engagement partner is responsible for the overall quality of the audit engagement, including direction and supervision of the engagement team, review of audit work, ensuring consultation on difficult issues, and making key judgments. Firm-wide quality management policies, HR policies, and inspection programs are firm-level responsibilities.',
 'easy'),

(1, 'Quality Management',
 'Under SQMS No. 1, which of the following best describes the monitoring and remediation component?',
 '["Evaluating engagement profitability", "An ongoing process of evaluating whether the system of quality management is designed, implemented, and operating effectively", "Training staff on new accounting standards", "Setting ethical requirements for the firm"]'::jsonb,
 1,
 'The monitoring and remediation component requires the firm to establish an ongoing monitoring process that evaluates whether the quality management system is functioning as intended. When deficiencies are identified, the firm must take remedial actions. This includes inspection of completed engagements and evaluation of quality indicators.',
 'medium'),

(1, 'Quality Management',
 'An audit firm is required to perform an engagement quality review for which of the following?',
 '["All compilation engagements", "All engagements for entities listed on a stock exchange", "Only engagements where a disagreement arose with management", "Only engagements lasting more than one year"]'::jsonb,
 1,
 'Engagement quality reviews are required for audits of listed entities (public companies) and other engagements for which the firm determines a review is appropriate based on quality risk assessments. Listed entity audits always require this additional quality safeguard. Compilations and the other scenarios listed do not trigger automatic requirements.',
 'medium'),

(1, 'Quality Management',
 'The engagement quality reviewer must be satisfied that significant judgments made by the engagement team are appropriate. Which of the following is the reviewer NOT required to do?',
 '["Review critical areas of judgment in the engagement", "Evaluate the engagement team''s assessment of the firm''s independence", "Reperform all audit procedures performed by the engagement team", "Read the financial statements and proposed audit report"]'::jsonb,
 2,
 'The engagement quality reviewer is not required to reperform all audit procedures. The role involves evaluating significant judgments, reviewing critical areas, assessing independence, and reading the financial statements and report. The reviewer provides an objective evaluation of the team''s key decisions rather than duplicating the audit work itself.',
 'hard'),

-- Professional Responsibilities (5 questions)
(1, 'Professional Responsibilities',
 'Under the AICPA Code of Professional Conduct, which of the following acts would constitute a violation of confidentiality?',
 '["Disclosing client information in response to a valid subpoena", "Sharing client financial data in a peer review", "Revealing client information to a friend at a social gathering without the client''s consent", "Providing client information to the client''s authorized representative"]'::jsonb,
 2,
 'Disclosing confidential client information without consent and without a valid legal or professional reason is a violation of confidentiality. Responses to valid subpoenas, peer reviews, and authorized representative requests are permitted exceptions. Social disclosure without client consent violates the rule regardless of the circumstances.',
 'easy'),

(1, 'Professional Responsibilities',
 'A CPA discovers potential illegal acts during an audit. If the illegal act has a material effect on the financial statements and management does not take appropriate remedial action, the CPA should:',
 '["Ignore it since detecting illegal acts is not the auditor''s responsibility", "Report it directly to law enforcement", "Consider the effect on the audit report and potentially withdraw from the engagement", "Disclose the illegal act in the notes to the financial statements"]'::jsonb,
 2,
 'When an auditor discovers a material illegal act and management fails to take remedial action, the auditor should consider the effect on the financial statements and the audit report. This may lead to a modified opinion or withdrawal from the engagement. The auditor generally does not have a duty to report directly to law enforcement (except under certain statutes) and cannot add notes to the client''s statements.',
 'medium'),

(1, 'Professional Responsibilities',
 'A CPA provides tax services to a company and is also asked to audit the same company. Under the AICPA conceptual framework, what type of threat does this create?',
 '["Advocacy threat", "Self-review threat", "Undue influence threat", "No threat, since tax services are always permitted for audit clients"]'::jsonb,
 1,
 'Providing tax services to an audit client may create a self-review threat if the tax work product is reflected in the financial statements being audited (e.g., tax provision). While tax preparation is generally permitted with appropriate safeguards, the CPA must evaluate the threat under the conceptual framework and ensure safeguards reduce it to an acceptable level.',
 'hard'),

(1, 'Professional Responsibilities',
 'What is the purpose of the AICPA''s peer review program?',
 '["To determine whether CPA firms are complying with applicable professional standards in their accounting and auditing practices", "To assess individual CPA performance on the CPA exam", "To establish tax filing requirements for CPA firms", "To discipline individual CPAs for ethical violations"]'::jsonb,
 0,
 'The peer review program evaluates whether a CPA firm''s system of quality control for its accounting and auditing practice is designed and operating in compliance with professional standards. It is a firm-level review, not an evaluation of individual performance, tax compliance, or disciplinary action.',
 'medium'),

(1, 'Professional Responsibilities',
 'A CPA learns that a tax return they prepared for a client contains a significant error from a prior year. What is the CPA''s professional responsibility?',
 '["File an amended return on behalf of the client without consent", "Promptly advise the client of the error and recommend corrective measures", "Report the error to the IRS directly", "Take no action since the prior-year return has already been filed"]'::jsonb,
 1,
 'When a CPA becomes aware of an error in a previously filed return, the CPA must promptly notify the client of the error and recommend corrective action, such as filing an amended return. The CPA cannot amend without client consent and generally has no obligation to report directly to the IRS. However, the CPA should consider whether to continue the relationship if the client refuses to correct it.',
 'medium'),

-- =============================================================================
-- FAR — Financial Accounting and Reporting (section_id = 2)
-- 50 questions: 13 easy, 24 medium, 13 hard
-- =============================================================================

-- Financial Statements (5 questions)
(2, 'Financial Statements',
 'Which of the following items would be classified as a current asset on the balance sheet?',
 '["A patent with a remaining useful life of 3 years", "Land held for future use", "Accounts receivable expected to be collected within 60 days", "A 5-year note receivable"]'::jsonb,
 2,
 'Current assets are assets expected to be converted to cash, sold, or consumed within one year or the operating cycle, whichever is longer. Accounts receivable expected to be collected within 60 days meets this definition. Patents and land held for future use are noncurrent, and a 5-year note receivable is a long-term asset.',
 'easy'),

(2, 'Financial Statements',
 'Under ASC 220, which of the following items is included in other comprehensive income (OCI)?',
 '["Cost of goods sold", "Unrealized gains on available-for-sale debt securities", "Depreciation expense", "Cash dividends declared"]'::jsonb,
 1,
 'Other comprehensive income includes items that bypass the income statement, such as unrealized gains and losses on available-for-sale debt securities, foreign currency translation adjustments, certain pension adjustments, and effective portions of cash flow hedges. Cost of goods sold and depreciation are income statement items, and dividends reduce retained earnings.',
 'medium'),

(2, 'Financial Statements',
 'A company has the following: total assets of $800,000, total liabilities of $500,000, and retained earnings of $150,000. What is the total contributed capital (paid-in capital)?',
 '["$150,000", "$300,000", "$500,000", "$650,000"]'::jsonb,
 0,
 'Using the accounting equation: Total equity = Assets - Liabilities = $800,000 - $500,000 = $300,000. Total equity = Contributed capital + Retained earnings. Therefore, Contributed capital = $300,000 - $150,000 = $150,000.',
 'easy'),

(2, 'Financial Statements',
 'Which of the following is classified as an operating activity on the statement of cash flows under the indirect method?',
 '["Payment of dividends to shareholders", "Proceeds from issuance of common stock", "Depreciation expense added back to net income", "Purchase of equipment"]'::jsonb,
 2,
 'Under the indirect method, net income is adjusted for noncash items and changes in working capital. Depreciation expense is a noncash charge that reduced net income but did not use cash, so it is added back in the operating activities section. Dividends are financing, stock issuance is financing, and equipment purchases are investing activities.',
 'easy'),

(2, 'Financial Statements',
 'ASC 280 requires segment reporting for public entities. Which of the following criteria qualifies a segment as a reportable segment?',
 '["The segment must have more than 50 employees", "The segment''s reported revenue is 10% or more of the combined revenue of all operating segments", "The segment must operate in a foreign country", "The segment must be profitable"]'::jsonb,
 1,
 'Under ASC 280, an operating segment is reportable if it meets any one of three quantitative thresholds: (1) its revenue is 10% or more of combined segment revenue, (2) its profit or loss is 10% or more of the greater of combined profit or combined loss, or (3) its assets are 10% or more of combined segment assets. Size, location, and profitability are not criteria.',
 'hard'),

-- Revenue Recognition (5 questions)
(2, 'Revenue Recognition',
 'Under ASC 606, when is a performance obligation satisfied over time?',
 '["Only when the customer makes the final payment", "When the entity has a present right to payment for performance completed to date and the customer receives and consumes benefits simultaneously, or the entity''s performance creates an asset with no alternative use", "When the contract is signed", "Only at the end of the contract period"]'::jsonb,
 1,
 'ASC 606 specifies three criteria for over-time recognition (any one is sufficient): (1) the customer simultaneously receives and consumes the benefits, (2) the entity''s performance creates or enhances a customer-controlled asset, or (3) the entity''s performance does not create an asset with alternative use and has an enforceable right to payment for performance completed to date.',
 'hard'),

(2, 'Revenue Recognition',
 'A company sells a product with a right of return within 30 days. How should the company account for the expected returns under ASC 606?',
 '["Recognize revenue for all units sold and record a contingent liability", "Recognize revenue only for units not expected to be returned and record a refund liability for expected returns", "Defer all revenue recognition until the return period expires", "Recognize revenue only when cash is received"]'::jsonb,
 1,
 'Under ASC 606, the company recognizes revenue for units not expected to be returned (using an estimated transaction price that excludes amounts expected to be refunded). A refund liability is recorded for the expected returns, and a right-of-return asset is recorded for the expected cost of returned inventory.',
 'medium'),

(2, 'Revenue Recognition',
 'A company offers a loyalty points program where customers earn points with purchases. Under ASC 606, how are the loyalty points accounted for?',
 '["As a marketing expense when points are earned", "As a separate performance obligation with a portion of the transaction price allocated to the points", "Ignored until points are redeemed", "As a contingent liability"]'::jsonb,
 1,
 'Under ASC 606, loyalty points that provide a material right to the customer (a discount on future purchases that they would not otherwise receive) are treated as a separate performance obligation. A portion of the transaction price is allocated to the points based on their standalone selling price and recognized as revenue when the points are redeemed or expire.',
 'hard'),

(2, 'Revenue Recognition',
 'Which of the following is a contract modification under ASC 606?',
 '["A change in the transaction price due to variable consideration", "A change approved by the parties to the contract that creates new or changes existing enforceable rights and obligations", "An exercise of an existing option in the contract", "A change in the entity''s accounting estimate"]'::jsonb,
 1,
 'A contract modification under ASC 606 is a change to the scope or price (or both) of a contract that is approved by the parties. It creates new or changes existing enforceable rights and obligations. Variable consideration adjustments, option exercises within existing terms, and accounting estimate changes are not contract modifications.',
 'medium'),

(2, 'Revenue Recognition',
 'A principal recognizes revenue at the gross amount of consideration, while an agent recognizes revenue at the net amount (commission). Which indicator suggests the entity is a principal?',
 '["The entity is exposed to credit risk only after the customer pays", "The entity controls the specified good or service before it is transferred to the customer", "The entity earns a fixed percentage commission on each transaction", "The entity does not bear inventory risk"]'::jsonb,
 1,
 'Under ASC 606, the primary indicator of whether an entity is a principal is whether it controls the specified good or service before it is transferred to the customer. Additional indicators include primary responsibility, inventory risk, and pricing discretion. An entity that controls the good is a principal and reports revenue gross.',
 'medium'),

-- Inventory (3 questions)
(2, 'Inventory',
 'A company uses the weighted-average cost method. Beginning inventory is 100 units at $10 each, and a purchase of 200 units at $13 each is made during the period. What is the weighted-average cost per unit?',
 '["$10.00", "$11.50", "$12.00", "$13.00"]'::jsonb,
 2,
 'Weighted-average cost = Total cost / Total units = (100 x $10 + 200 x $13) / (100 + 200) = ($1,000 + $2,600) / 300 = $3,600 / 300 = $12.00 per unit. This method averages the cost of all available units regardless of when they were purchased.',
 'easy'),

(2, 'Inventory',
 'Under ASC 330, inventory should be measured at the lower of cost or net realizable value (NRV). How is NRV defined?',
 '["Selling price minus costs to complete and dispose", "Historical cost minus accumulated depreciation", "Replacement cost", "Fair value less costs to sell"]'::jsonb,
 0,
 'Net realizable value is the estimated selling price in the ordinary course of business, less reasonably predictable costs of completion, disposal, and transportation. This replaced the lower of cost or market framework (which used replacement cost with floor and ceiling constraints) following ASU 2015-11 for entities using FIFO or weighted-average.',
 'medium'),

(2, 'Inventory',
 'A retail company uses the retail inventory method. Which of the following is a primary purpose of this method?',
 '["To determine the exact cost of each item sold", "To estimate the cost of ending inventory based on the cost-to-retail ratio", "To track individual item profitability", "To comply with income tax requirements"]'::jsonb,
 1,
 'The retail inventory method estimates ending inventory cost by applying the cost-to-retail percentage (cost of goods available / retail price of goods available) to the ending inventory at retail. This method is efficient for retailers with large volumes of similar items where tracking individual item costs is impractical.',
 'medium'),

-- Fixed Assets (3 questions)
(2, 'Fixed Assets',
 'Which of the following costs should be capitalized as part of the cost of a building?',
 '["Annual property taxes after the building is placed in service", "Architectural fees incurred during construction", "Repairs to maintain the building after occupancy", "General and administrative overhead of the company"]'::jsonb,
 1,
 'Costs necessary to prepare an asset for its intended use are capitalized. Architectural fees are directly related to the construction of the building and are capitalized as part of its cost. Property taxes after the building is in service, routine repairs, and G&A overhead are period expenses, not capitalizable costs.',
 'easy'),

(2, 'Fixed Assets',
 'A company owns equipment with a carrying amount of $400,000. The equipment''s fair value is $350,000 and the expected undiscounted future cash flows from using the equipment are $380,000. Under ASC 360, is the equipment impaired?',
 '["Yes, because carrying amount exceeds fair value", "No, because the undiscounted future cash flows of $380,000 are less than the carrying amount of $400,000 — wait, this means it IS impaired", "No, because the undiscounted future cash flows of $380,000 do not exceed the carrying amount of $400,000, so the asset fails the recoverability test and is impaired", "Yes, impairment loss is $50,000"]'::jsonb,
 3,
 'Under ASC 360, long-lived assets are tested for impairment using a two-step approach. Step 1: Compare carrying amount to undiscounted future cash flows (recoverability test). Since $380,000 < $400,000, the asset is not recoverable. Step 2: Measure impairment as carrying amount minus fair value = $400,000 - $350,000 = $50,000 impairment loss.',
 'hard'),

(2, 'Fixed Assets',
 'A company changes its depreciation method from straight-line to double-declining balance. Under ASC 250, how is this change treated?',
 '["As a change in accounting principle requiring retrospective application", "As a change in accounting estimate effected by a change in accounting principle, applied prospectively", "As a correction of an error requiring restatement", "As an extraordinary item"]'::jsonb,
 1,
 'Under ASC 250, a change in depreciation method is treated as a change in accounting estimate effected by a change in accounting principle. Such changes are accounted for prospectively — the new method is applied to the current and future periods. No retrospective adjustment or restatement is required.',
 'hard'),

-- Intangible Assets (3 questions)
(2, 'Intangible Assets',
 'Under U.S. GAAP, research and development costs are generally:',
 '["Capitalized as an intangible asset", "Expensed as incurred", "Deferred and amortized over the expected benefit period", "Reported as other comprehensive income"]'::jsonb,
 1,
 'Under ASC 730, research and development costs are generally expensed as incurred because the future economic benefits are uncertain at the time the costs are incurred. There are limited exceptions, such as R&D acquired in a business combination (capitalized at fair value) and software development costs after technological feasibility is established.',
 'easy'),

(2, 'Intangible Assets',
 'A company develops a software product for external sale. Under ASC 985-20, at what point should the company begin capitalizing software development costs?',
 '["When the project is first conceived", "After technological feasibility has been established", "When the first sale is made", "After all coding is complete"]'::jsonb,
 1,
 'Under ASC 985-20, costs of developing software for external sale are expensed until technological feasibility is established (evidenced by a detailed program design or working model). After that point, costs are capitalized until the product is available for general release. Costs incurred after general availability are expensed.',
 'medium'),

(2, 'Intangible Assets',
 'A company acquires another company and recognizes $2 million in goodwill. Under the current GAAP qualitative assessment for goodwill impairment, what must the company evaluate?',
 '["Whether the fair value of the reporting unit has decreased below its carrying amount, considering qualitative factors first", "Whether the goodwill has generated sufficient revenue", "Whether the original purchase price was reasonable", "Whether the goodwill has been fully amortized"]'::jsonb,
 0,
 'Under the qualitative assessment (Step 0), the company evaluates whether it is more likely than not that the fair value of the reporting unit is less than its carrying amount. Qualitative factors include macroeconomic conditions, industry and market trends, entity-specific events, and financial performance. If it is not more likely than not, no further testing is required.',
 'medium'),

-- Leases (3 questions)
(2, 'Leases',
 'Under ASC 842, what is the short-term lease exemption threshold?',
 '["6 months", "12 months", "24 months", "36 months"]'::jsonb,
 1,
 'ASC 842 provides a practical expedient allowing lessees to elect not to recognize right-of-use assets and lease liabilities for leases with a term of 12 months or less at commencement, provided the lease does not include a purchase option that the lessee is reasonably certain to exercise. Short-term lease payments are recognized as expense on a straight-line basis.',
 'easy'),

(2, 'Leases',
 'A lessee has a finance lease. How is the right-of-use asset amortized?',
 '["It is not amortized — only the lease liability is reduced", "On a straight-line basis over the shorter of the lease term or the useful life of the underlying asset", "Using the effective interest method", "Over the remaining economic life of the building"]'::jsonb,
 1,
 'For a finance lease, the right-of-use asset is amortized generally on a straight-line basis over the shorter of the lease term or the useful life of the underlying asset (unless ownership transfers or a purchase option is reasonably certain, in which case the useful life is used). The lease liability is reduced using the effective interest method.',
 'medium'),

(2, 'Leases',
 'A lessor classifies a lease as a sales-type lease. What amounts does the lessor recognize at lease commencement?',
 '["Only rental income over the lease term", "A net investment in the lease (lease receivable and any unguaranteed residual asset), selling profit or loss, and derecognition of the underlying asset", "A right-of-use asset and a lease liability", "No amounts at commencement — everything is recognized over the lease term"]'::jsonb,
 1,
 'In a sales-type lease, the lessor derecognizes the underlying asset, recognizes a net investment in the lease (present value of lease payments and residual value), and recognizes any selling profit or loss (difference between fair value and carrying amount of the asset). This treatment reflects that the lessor has effectively sold the asset.',
 'hard'),

-- Bonds and Debt (3 questions)
(2, 'Bonds and Debt',
 'When bonds are issued at a premium, the stated interest rate is:',
 '["Equal to the market rate", "Less than the market rate", "Greater than the market rate", "Unrelated to the market rate"]'::jsonb,
 2,
 'Bonds sell at a premium when the stated (coupon) rate exceeds the market (effective) rate at issuance. Investors pay more than face value because the bond''s fixed interest payments are more attractive than current market rates. The premium is amortized over the bond''s life, reducing interest expense below the cash interest paid.',
 'easy'),

(2, 'Bonds and Debt',
 'A company issues $1,000,000 of bonds at 103 with a 10-year term. Using the straight-line method, what is the annual premium amortization?',
 '["$3,000", "$30,000", "$10,000", "$10,300"]'::jsonb,
 0,
 'The premium is $1,000,000 x 3% = $30,000. Under the straight-line method, this premium is amortized evenly over the 10-year term: $30,000 / 10 = $3,000 per year. Each year, interest expense is reduced by $3,000 (cash interest paid minus premium amortization).',
 'medium'),

(2, 'Bonds and Debt',
 'A company extinguishes bonds payable before maturity by purchasing them on the open market. The carrying amount of the bonds is $970,000 and the company pays $985,000 to retire them. How is this transaction reported?',
 '["$15,000 gain on early extinguishment", "$15,000 loss on early extinguishment", "No gain or loss is recognized", "$15,000 reduction in bonds payable"]'::jsonb,
 1,
 'The difference between the carrying amount ($970,000) and the reacquisition price ($985,000) results in a $15,000 loss on early extinguishment. Under ASC 470-50, gains and losses on early debt extinguishment are recognized in income in the period of extinguishment. Since the company paid more than the carrying amount, it is a loss.',
 'medium'),

-- Equity (3 questions)
(2, 'Equity',
 'A company splits its stock 2-for-1. Before the split, there were 100,000 shares outstanding at $2 par value. After the split, how many shares are outstanding and at what par value?',
 '["200,000 shares at $2 par", "200,000 shares at $1 par", "100,000 shares at $1 par", "50,000 shares at $4 par"]'::jsonb,
 1,
 'In a 2-for-1 stock split, the number of shares doubles and the par value per share is halved. After the split: 100,000 x 2 = 200,000 shares at $2 / 2 = $1 par value. Total par value remains the same ($200,000). No journal entry is required — only a memo entry noting the change in shares and par value.',
 'easy'),

(2, 'Equity',
 'When treasury stock is reissued at a price above its cost (under the cost method), the excess is credited to:',
 '["Gain on sale of treasury stock", "Retained earnings", "Additional paid-in capital from treasury stock transactions", "Other comprehensive income"]'::jsonb,
 2,
 'When treasury stock is reissued above cost, the excess is credited to additional paid-in capital (APIC) from treasury stock transactions, not to gain. Corporations cannot recognize gains or losses on transactions involving their own stock. If reissued below cost, the deficit is debited to APIC from prior treasury stock transactions, then retained earnings if APIC is insufficient.',
 'medium'),

(2, 'Equity',
 'A company declares a property dividend of investments with a carrying amount of $100,000 and a fair value of $140,000. What is the journal entry on the declaration date?',
 '["Debit Retained Earnings $100,000; Credit Property Dividends Payable $100,000", "Debit Retained Earnings $140,000; Credit Property Dividends Payable $140,000; and recognize a $40,000 gain on the investment", "Debit Retained Earnings $140,000; Credit Property Dividends Payable $140,000 (no separate gain)", "No entry until distribution date"]'::jsonb,
 1,
 'Property dividends are recorded at fair value. On the declaration date, the company first remeasures the asset to fair value, recognizing a $40,000 gain ($140,000 - $100,000). Then retained earnings is debited and property dividends payable is credited for $140,000 (the fair value). The net effect includes both the gain recognition and the dividend declaration.',
 'hard'),

-- Income Taxes (4 questions)
(2, 'Income Taxes',
 'Which of the following creates a permanent difference between book and taxable income?',
 '["Depreciation differences between MACRS and straight-line", "Warranty expense accrual", "Municipal bond interest income", "Prepaid rent received in advance"]'::jsonb,
 2,
 'Municipal bond interest is exempt from federal income tax but is included in book income, creating a permanent difference. Permanent differences never reverse and result in differences between the statutory and effective tax rates. Depreciation, warranty accruals, and prepaid rent create temporary differences that reverse over time.',
 'medium'),

(2, 'Income Taxes',
 'A company reports pretax book income of $1,000,000. It has $50,000 in permanent differences (tax-exempt income) and $100,000 in temporary differences (depreciation). The tax rate is 21%. What is the current income tax expense?',
 '["$178,500", "$210,000", "$199,500", "$221,000"]'::jsonb,
 0,
 'Taxable income = Book income - Permanent differences - Temporary differences = $1,000,000 - $50,000 - $100,000 = $850,000. Current tax expense = $850,000 x 21% = $178,500. The permanent difference reduces both taxable income and current tax, while the temporary difference creates a deferred tax liability of $100,000 x 21% = $21,000.',
 'hard'),

(2, 'Income Taxes',
 'Under ASC 740, an uncertain tax position can be recognized only if it is:',
 '["More likely than not to be sustained upon examination by the taxing authority", "Virtually certain to be sustained", "Probable of being sustained", "Reasonably possible of being sustained"]'::jsonb,
 0,
 'ASC 740-10 uses a two-step approach for uncertain tax positions. Step 1 (recognition): The benefit is recognized only if it is more likely than not (greater than 50%) that the position will be sustained. Step 2 (measurement): The recognized benefit is measured at the largest amount that is greater than 50% likely to be realized upon settlement.',
 'medium'),

(2, 'Income Taxes',
 'A deferred tax asset or liability should be classified as current or noncurrent based on:',
 '["Whether the related tax return is due within one year", "The classification of the related asset or liability in the balance sheet (all classified as noncurrent under ASU 2015-17)", "The expected date of reversal only", "Whether the entity is public or private"]'::jsonb,
 1,
 'Under ASU 2015-17, all deferred tax assets and liabilities are classified as noncurrent on the balance sheet. This simplified the previous requirement to classify deferred taxes based on the classification of the related asset or liability. The update applies to all entities and eliminates the need for current/noncurrent allocation.',
 'medium'),

-- Governmental Accounting (5 questions)
(2, 'Governmental Accounting',
 'What is the measurement focus of governmental funds?',
 '["Economic resources measurement focus", "Current financial resources measurement focus", "Cash basis measurement focus", "Accrual measurement focus"]'::jsonb,
 1,
 'Governmental funds use the current financial resources measurement focus, which means they report on the sources, uses, and balances of current financial resources (cash and items expected to be converted to cash soon). This differs from proprietary and fiduciary funds, which use the economic resources measurement focus (full accrual basis).',
 'easy'),

(2, 'Governmental Accounting',
 'Under GASB standards, when should a government recognize property tax revenue?',
 '["When the tax assessment is mailed to property owners", "In the period for which the taxes are levied, provided they are collected within 60 days of year-end (available)", "When cash is received from taxpayers", "When the tax rate is established by the governing body"]'::jsonb,
 1,
 'Under modified accrual accounting, revenue is recognized when it is both measurable and available. For property taxes, revenue is recognized in the period for which the taxes are levied, provided they are collected within the availability period (typically 60 days after year-end). Taxes collected beyond the availability period are reported as deferred inflows.',
 'medium'),

(2, 'Governmental Accounting',
 'The government-wide financial statements present information using which basis of accounting?',
 '["Modified accrual basis", "Cash basis", "Full accrual basis", "Income tax basis"]'::jsonb,
 2,
 'Government-wide financial statements (statement of net position and statement of activities) use the economic resources measurement focus and the full accrual basis of accounting, similar to private-sector entities. This contrasts with governmental fund financial statements, which use the modified accrual basis.',
 'easy'),

(2, 'Governmental Accounting',
 'A government issues general obligation bonds to finance construction of a new fire station. In which fund is the bond proceeds reported?',
 '["General fund", "Debt service fund", "Capital projects fund", "Enterprise fund"]'::jsonb,
 2,
 'Bond proceeds for capital construction are reported in a capital projects fund, which accounts for resources used for the acquisition or construction of major capital facilities. The debt service fund accounts for the repayment of principal and interest, and the general fund handles routine operations.',
 'medium'),

(2, 'Governmental Accounting',
 'Under GASB 87 (leases), how does a government lessee account for a lease with a term greater than 12 months?',
 '["As an operating expense over the lease term", "By recognizing a lease liability and an intangible right-to-use lease asset", "The same as ASC 842 with finance and operating classifications", "No recognition is required for governmental funds"]'::jsonb,
 1,
 'Under GASB 87, all leases with terms greater than 12 months (that are not short-term or meet other exceptions) are accounted for by recognizing a lease liability and an intangible right-to-use lease asset. GASB 87 uses a single model (no finance/operating distinction as in ASC 842) for government lessees.',
 'hard'),

-- Not-for-Profit Accounting (3 questions)
(2, 'Not-for-Profit Accounting',
 'A not-for-profit organization receives a conditional promise to give. When should the revenue be recognized?',
 '["When the pledge is made", "When the conditions are substantially met", "When the cash is received", "Conditional promises to give are never recognized"]'::jsonb,
 1,
 'Conditional promises to give depend on the occurrence of a specified uncertain future event. Revenue is recognized only when the conditions are substantially met (or the donor explicitly releases the condition). Until then, the conditional promise is not recognized as revenue but may be disclosed in the notes to the financial statements.',
 'medium'),

(2, 'Not-for-Profit Accounting',
 'A not-for-profit organization receives donated services from a licensed electrician who rewires the building. How should this be reported?',
 '["It is not recognized because donated services are never recorded", "Recognized as both revenue (contribution) and expense at fair value because the services create or enhance a nonfinancial asset", "Recognized only if the electrician provides a bill", "Recognized as a footnote disclosure only"]'::jsonb,
 1,
 'Under ASC 958, donated services are recognized if they (1) create or enhance nonfinancial assets, or (2) require specialized skills, are provided by someone possessing those skills, and would typically need to be purchased if not donated. Rewiring a building by a licensed electrician meets both criteria. The services are recorded at fair value as both contribution revenue and expense.',
 'medium'),

(2, 'Not-for-Profit Accounting',
 'How should a not-for-profit organization report expenses in its financial statements?',
 '["By function only (program, management and general, fundraising)", "By nature only (salaries, rent, supplies)", "By both function and nature, either on the face of the statements or in the notes", "Expenses need not be reported — only revenues"]'::jsonb,
 2,
 'Under ASU 2016-14, not-for-profit organizations must report expenses by both their functional classification (program services, management and general, fundraising) and their natural classification (salaries, rent, depreciation, etc.). This can be presented on the face of the statement of activities, in a separate statement, or in the notes.',
 'hard'),

-- Consolidations (3 questions)
(2, 'Consolidations',
 'A parent company owns 70% of a subsidiary. In the consolidated income statement, how is the subsidiary''s net income presented?',
 '["Only 70% of the subsidiary''s income is included", "100% of the subsidiary''s income is included, with the 30% noncontrolling interest share deducted at the bottom", "The subsidiary''s income is reported as a single line item (equity method)", "It depends on whether the subsidiary is consolidated or not"]'::jsonb,
 1,
 'In consolidated financial statements, 100% of the subsidiary''s revenues and expenses are included in the consolidated income statement. The noncontrolling interest''s share (30%) of the subsidiary''s net income is then deducted as a separate line item at the bottom to arrive at net income attributable to the parent. This reflects the economic entity concept.',
 'medium'),

(2, 'Consolidations',
 'At what ownership level is consolidation generally required under U.S. GAAP?',
 '["Any ownership interest above 20%", "A controlling financial interest, typically more than 50% of voting shares", "Exactly 50% ownership", "Only 100% ownership"]'::jsonb,
 1,
 'Under ASC 810, consolidation is required when one entity has a controlling financial interest in another. For voting interest entities, this is typically more than 50% of the outstanding voting shares. For variable interest entities (VIEs), consolidation is required by the primary beneficiary regardless of ownership percentage.',
 'easy'),

(2, 'Consolidations',
 'During consolidation, goodwill is tested for impairment at what level?',
 '["The individual asset level", "The subsidiary level", "The reporting unit level", "The consolidated entity level"]'::jsonb,
 2,
 'Under ASC 350, goodwill is tested for impairment at the reporting unit level. A reporting unit is an operating segment or one level below an operating segment (a component). Goodwill is allocated to reporting units that benefit from the synergies of the business combination, and impairment testing occurs at that level.',
 'medium'),

-- Statement of Cash Flows (4 questions)
(2, 'Statement of Cash Flows',
 'Under the indirect method for operating activities, a decrease in accounts receivable is:',
 '["Subtracted from net income", "Added to net income", "Reported as an investing activity", "Not reported on the statement of cash flows"]'::jsonb,
 1,
 'A decrease in accounts receivable means more cash was collected than revenue recognized, representing a source of cash. Under the indirect method, decreases in current assets are added to net income to reconcile to cash from operations. Conversely, increases in current assets would be subtracted.',
 'easy'),

(2, 'Statement of Cash Flows',
 'A company reports net income of $500,000 for the year. During the year, depreciation was $80,000, accounts receivable increased by $30,000, accounts payable decreased by $15,000, and a $50,000 gain on sale of equipment was recognized. What is cash from operating activities?',
 '["$485,000", "$545,000", "$465,000", "$515,000"]'::jsonb,
 0,
 'Starting with net income: $500,000 + $80,000 (add back depreciation) - $30,000 (subtract AR increase) - $15,000 (subtract AP decrease) - $50,000 (subtract gain on sale, which is an investing activity) = $485,000. The gain is removed from operations because the full cash proceeds are reported in investing activities.',
 'medium'),

(2, 'Statement of Cash Flows',
 'Which of the following is classified as a financing activity?',
 '["Purchase of a patent", "Collection of a note receivable", "Payment of dividends to shareholders", "Receipt of interest on investments"]'::jsonb,
 2,
 'Financing activities involve transactions with owners and creditors of the entity, including issuing and repurchasing stock, borrowing and repaying debt, and paying dividends. Purchasing a patent is investing, collecting a note receivable is investing, and receiving interest is operating (or investing, depending on the nature).',
 'easy'),

(2, 'Statement of Cash Flows',
 'A company exchanges old equipment (book value $50,000) plus $120,000 cash for new equipment. How is this reported on the statement of cash flows?',
 '["$120,000 outflow in investing activities and the noncash exchange disclosed in a supplemental schedule", "Only $120,000 outflow in investing activities", "$170,000 outflow in investing activities", "No cash flow effect"]'::jsonb,
 0,
 'The $120,000 cash paid is reported as an investing outflow. The noncash portion (exchange of old equipment for new) is a noncash investing activity that must be disclosed either in supplemental information accompanying the statement of cash flows or in the notes, as required by ASC 230.',
 'hard'),

-- Additional topics (6 questions)
(2, 'Contingencies',
 'Under ASC 450, when should a loss contingency be accrued?',
 '["When the loss is possible and the amount can be estimated", "When the loss is probable and the amount can be reasonably estimated", "When the loss is remote", "Only when the loss is certain"]'::jsonb,
 1,
 'ASC 450 requires accrual of a loss contingency when two conditions are met: (1) it is probable that an asset has been impaired or a liability has been incurred, and (2) the amount can be reasonably estimated. If probable but not estimable, or reasonably possible, disclosure is required but no accrual. Remote contingencies generally require no disclosure.',
 'easy'),

(2, 'Contingencies',
 'A company is the defendant in a lawsuit. Legal counsel advises that an unfavorable outcome is reasonably possible, with estimated damages between $200,000 and $500,000. How should this be reported?',
 '["Accrue $200,000 as a liability", "Accrue $350,000 (the midpoint) as a liability", "Disclose the nature of the contingency and the range of possible loss in the notes", "No disclosure or accrual is necessary"]'::jsonb,
 2,
 'When a loss contingency is reasonably possible (but not probable), no accrual is required. However, ASC 450 requires disclosure of the nature of the contingency and an estimate of the possible loss or range of loss (or a statement that an estimate cannot be made). The $200,000-$500,000 range should be disclosed in the notes.',
 'medium'),

(2, 'Earnings Per Share',
 'Basic earnings per share is calculated by dividing net income available to common shareholders by:',
 '["Total shares authorized", "Total shares issued", "Weighted-average common shares outstanding during the period", "Shares outstanding at year-end"]'::jsonb,
 2,
 'Basic EPS uses the weighted-average number of common shares outstanding during the period as the denominator. This accounts for shares issued or repurchased during the year by weighting them for the portion of the period they were outstanding. Net income is reduced by preferred dividends to arrive at income available to common shareholders.',
 'easy'),

(2, 'Earnings Per Share',
 'A company has 100,000 weighted-average shares outstanding and net income of $500,000. There are 10,000 dilutive stock options with an exercise price of $20 when the average market price is $40. Using the treasury stock method, what is diluted EPS?',
 '["$5.00", "$4.76", "$4.55", "$4.35"]'::jsonb,
 1,
 'Treasury stock method: 10,000 options exercised would bring in $200,000 (10,000 x $20). At the average market price of $40, the company could repurchase 5,000 shares ($200,000 / $40). Net new shares = 10,000 - 5,000 = 5,000. Diluted EPS = $500,000 / (100,000 + 5,000) = $500,000 / 105,000 = $4.76.',
 'hard'),

(2, 'Fair Value',
 'Under ASC 820, the fair value hierarchy classifies inputs into three levels. What are Level 1 inputs?',
 '["Management''s internal estimates", "Quoted prices in active markets for identical assets or liabilities", "Observable inputs other than Level 1 prices", "Unobservable inputs based on the entity''s own assumptions"]'::jsonb,
 1,
 'Level 1 inputs are quoted prices (unadjusted) in active markets for identical assets or liabilities that the entity can access at the measurement date. These are the most reliable and preferred inputs. Level 2 includes other observable inputs, and Level 3 includes unobservable inputs (least reliable).',
 'medium'),

(2, 'Fair Value',
 'An entity measures a nonfinancial asset at fair value. Under ASC 820, the fair value measurement should reflect:',
 '["The cost the entity originally paid for the asset", "The highest and best use of the asset from the perspective of market participants", "The asset''s value in its current use only", "The liquidation value of the asset"]'::jsonb,
 1,
 'For nonfinancial assets, ASC 820 requires that fair value reflect the highest and best use from a market participant''s perspective. This may differ from the entity''s current use. Highest and best use considers what is physically possible, legally permissible, and financially feasible. Financial assets do not have a highest-and-best-use concept.',
 'hard'),

-- =============================================================================
-- REG — Taxation and Regulation (section_id = 3)
-- 50 questions: 13 easy, 24 medium, 13 hard
-- =============================================================================

-- Circular 230 (3 questions)
(3, 'Circular 230',
 'Which of the following sanctions can the IRS Office of Professional Responsibility impose on a practitioner who violates Circular 230?',
 '["Criminal imprisonment", "Censure, suspension, or disbarment from practice before the IRS", "Revocation of the practitioner''s CPA license", "Seizure of the practitioner''s personal assets"]'::jsonb,
 1,
 'The IRS Office of Professional Responsibility can impose censure (public reprimand), suspension, or disbarment from practice before the IRS. It cannot impose criminal penalties (that requires DOJ prosecution), revoke CPA licenses (that is a state board function), or seize assets. Monetary penalties may also be imposed for certain violations.',
 'medium'),

(3, 'Circular 230',
 'Under Circular 230, a practitioner may not charge an unconscionable fee for services. Which of the following factors is relevant in determining whether a fee is unconscionable?',
 '["Whether the practitioner''s office is in an expensive location", "The experience, reputation, and ability of the practitioner and the complexity of the work", "Whether the client is a large corporation or individual", "The number of years the practitioner has been in practice"]'::jsonb,
 1,
 'Factors in determining whether a fee is unconscionable include the complexity and novelty of the work, the practitioner''s experience and ability, the time and labor required, customary fees for similar services, and the results obtained. Office location, client size, and years of practice alone are not determinative.',
 'medium'),

(3, 'Circular 230',
 'A practitioner signs a tax return that contains a position not supported by substantial authority. Which of the following describes the practitioner''s responsibility?',
 '["The practitioner has no responsibility if the client instructed them to take the position", "The position must have at least a reasonable basis and be adequately disclosed on the return", "Any position can be taken without disclosure", "The practitioner must obtain a private letter ruling before taking the position"]'::jsonb,
 1,
 'Under Circular 230, a practitioner may not sign a return containing a position unless there is a reasonable basis for the position. If the position does not meet the substantial authority standard, it must be adequately disclosed on the return (e.g., Form 8275). This prevents frivolous positions while allowing legitimate disagreements with IRS interpretations.',
 'hard'),

-- Business Law: Contracts (4 questions)
(3, 'Business Law: Contracts',
 'Which of the following is valid consideration in a contract?',
 '["A promise to do something one is already legally obligated to do", "A promise to forbear from exercising a legal right", "Past consideration for services already rendered", "A moral obligation to help a friend"]'::jsonb,
 1,
 'Valid consideration requires a bargained-for exchange of something of legal value. A promise to forbear (refrain from doing something one has a legal right to do) constitutes valid consideration. A pre-existing duty is not new consideration, past consideration is not bargained-for, and moral obligations lack legal enforceability.',
 'medium'),

(3, 'Business Law: Contracts',
 'Under the UCC Article 2, the perfect tender rule applies to contracts for the sale of goods. What does this rule provide?',
 '["The seller must deliver goods that conform perfectly to the contract terms, or the buyer may reject the entire shipment", "The buyer must accept any goods delivered as long as they are substantially similar", "The seller has unlimited opportunities to cure defective tender", "The rule only applies to contracts over $500"]'::jsonb,
 0,
 'The perfect tender rule under UCC 2-601 allows a buyer to reject goods if they fail to conform to the contract in any respect. The buyer can accept all, reject all, or accept some and reject the rest. However, the seller generally has the right to cure (correct the deficiency) if the time for performance has not yet expired.',
 'medium'),

(3, 'Business Law: Contracts',
 'A contract is voidable if:',
 '["Both parties were mistaken about a basic assumption of the contract", "One party had greater bargaining power", "The subject matter of the contract is destroyed", "The contract was formed by mutual agreement"]'::jsonb,
 0,
 'A contract is voidable (can be rescinded by the adversely affected party) in cases of mutual mistake about a basic assumption that materially affects the exchange. Unequal bargaining power alone does not make a contract voidable (unless it rises to unconscionability). Destruction of subject matter may make the contract impossible, and mutual agreement forms a valid contract.',
 'hard'),

(3, 'Business Law: Contracts',
 'A minor enters into a contract to purchase a car. Which of the following is true?',
 '["The contract is void and has no legal effect", "The contract is voidable at the option of the minor", "The contract is fully enforceable against the minor", "The contract is voidable at the option of the adult party"]'::jsonb,
 1,
 'Contracts with minors are voidable at the minor''s option. The minor can choose to disaffirm (void) the contract either during minority or within a reasonable time after reaching the age of majority. The adult party is bound by the contract and cannot void it. If the minor ratifies the contract after reaching majority, it becomes fully enforceable.',
 'easy'),

-- Agency and Regulation (3 questions)
(3, 'Agency and Regulation',
 'An agent who acts beyond the scope of their authority may still bind the principal if:',
 '["The agent believed they had authority", "The principal ratifies the unauthorized act after learning of it", "The third party was unaware of the agency relationship", "The agent had good intentions"]'::jsonb,
 1,
 'A principal may ratify an unauthorized act of the agent after the fact, thereby binding themselves to the transaction. Ratification requires the principal to have full knowledge of the material facts, the act must be ratifiable, and the principal must ratify the entire transaction. The agent''s belief, the third party''s knowledge, and the agent''s intentions alone do not create binding authority.',
 'medium'),

(3, 'Agency and Regulation',
 'In an agency relationship, the agent owes the principal several fiduciary duties. Which of the following is NOT a fiduciary duty of the agent?',
 '["Duty of loyalty", "Duty of obedience", "Duty to guarantee the success of the principal''s business", "Duty of care"]'::jsonb,
 2,
 'An agent owes the principal fiduciary duties including loyalty (avoiding conflicts of interest), obedience (following lawful instructions), care (acting with reasonable diligence), accounting (maintaining records of transactions), and notification (informing the principal of relevant matters). There is no duty to guarantee business success.',
 'easy'),

(3, 'Agency and Regulation',
 'A disclosed principal engages an agent to enter contracts on their behalf. If the agent signs a contract within the scope of authority, who is liable on the contract?',
 '["Only the agent", "Only the principal", "Both the agent and the principal", "Neither — the contract is void"]'::jsonb,
 1,
 'When an agent acts on behalf of a disclosed principal (one whose identity is known to the third party) and within the scope of authority, only the principal is liable on the contract. The agent drops out of the transaction. If the principal is partially disclosed or undisclosed, the agent may also be liable.',
 'medium'),

-- Business Structures (4 questions)
(3, 'Business Structures',
 'Which of the following is a disadvantage of a general partnership?',
 '["Double taxation of profits", "Limited ability to raise capital through stock issuance", "Unlimited personal liability of all partners for partnership debts", "Required annual shareholder meetings"]'::jsonb,
 2,
 'The primary disadvantage of a general partnership is that all partners have unlimited personal liability for the debts and obligations of the partnership. Each partner can be held personally responsible for the full amount of partnership debts, not just their share. Partnerships are pass-through entities (no double taxation) and do not issue stock.',
 'easy'),

(3, 'Business Structures',
 'A limited partnership must have at least:',
 '["One general partner and one limited partner", "Two general partners", "Two limited partners", "Three partners of any type"]'::jsonb,
 0,
 'A limited partnership requires at least one general partner (who manages the business and has unlimited liability) and at least one limited partner (who contributes capital and has liability limited to their investment). The general partner manages the business while limited partners are passive investors.',
 'easy'),

(3, 'Business Structures',
 'Which of the following is true about a limited liability partnership (LLP)?',
 '["Partners have no liability for any partnership debts", "Partners are not personally liable for the negligence or malpractice of other partners, but may remain liable for their own acts and general partnership obligations", "LLPs are taxed as corporations", "LLPs cannot be formed by professional service firms"]'::jsonb,
 1,
 'In an LLP, partners are shielded from personal liability for the negligence, malpractice, or misconduct of other partners. However, partners remain liable for their own negligent or wrongful acts and may still be liable for general partnership contractual obligations. LLPs are popular among professional firms (accounting, law) for this reason.',
 'medium'),

(3, 'Business Structures',
 'A shareholder of a corporation generally has which of the following rights?',
 '["The right to manage daily operations of the corporation", "The right to vote on major corporate matters, receive dividends when declared, and inspect corporate books", "The right to bind the corporation in contracts", "The right to transfer corporate assets"]'::jsonb,
 1,
 'Shareholders have the right to vote on major matters (election of directors, mergers, amendments), receive dividends when declared, inspect books and records, and receive assets upon liquidation (after creditors). Daily management is the responsibility of directors and officers. Shareholders cannot bind the corporation or unilaterally transfer corporate assets.',
 'medium'),

-- Property Transactions: Basis (3 questions)
(3, 'Property Transactions: Basis',
 'A taxpayer purchases a rental property for $250,000. Of this amount, $50,000 is allocated to land and $200,000 to the building. What is the depreciable basis of the rental property?',
 '["$250,000", "$200,000", "$50,000", "$125,000"]'::jsonb,
 1,
 'Only the building portion is depreciable — land is never depreciated because it has an unlimited useful life. The depreciable basis is $200,000 (the building cost). Residential rental property is depreciated over 27.5 years using the straight-line method under MACRS.',
 'easy'),

(3, 'Property Transactions: Basis',
 'A taxpayer converts a personal residence to rental property. The original cost was $300,000, and the FMV at conversion date is $260,000. What is the basis for depreciation?',
 '["$300,000", "$260,000", "$280,000", "The higher of cost or FMV"]'::jsonb,
 1,
 'When personal-use property is converted to business or rental use, the basis for depreciation is the lower of the adjusted basis (cost, if no adjustments) or the FMV at the date of conversion. Since FMV ($260,000) is less than cost ($300,000), the depreciable basis is $260,000. This prevents deducting personal economic losses through depreciation.',
 'hard'),

(3, 'Property Transactions: Basis',
 'A taxpayer receives property in a taxable exchange. The property received has a FMV of $100,000. The taxpayer gave up property with an adjusted basis of $70,000 and FMV of $85,000, plus $15,000 cash. What is the basis of the property received?',
 '["$100,000", "$85,000", "$70,000", "$115,000"]'::jsonb,
 0,
 'In a taxable exchange, the basis of property received is its fair market value ($100,000). The taxpayer recognizes a gain of $100,000 - ($70,000 + $15,000) = $15,000. In taxable transactions, the basis of property received equals its FMV because all gain or loss is recognized immediately.',
 'medium'),

-- Property Transactions: Gains/Losses (4 questions)
(3, 'Property Transactions: Gains/Losses',
 'A taxpayer sells stock held for 8 months at a gain. How is this gain characterized?',
 '["Long-term capital gain", "Short-term capital gain", "Ordinary income", "Section 1231 gain"]'::jsonb,
 1,
 'Capital assets held for one year or less generate short-term capital gains or losses. Since the stock was held for only 8 months, the gain is a short-term capital gain, taxed at ordinary income rates. To qualify for preferential long-term capital gain rates, the holding period must exceed one year.',
 'easy'),

(3, 'Property Transactions: Gains/Losses',
 'A taxpayer has net short-term capital losses of $8,000 and net long-term capital gains of $5,000 for the year. What is the net capital gain or loss, and how much can be deducted against ordinary income?',
 '["$3,000 net capital loss; $3,000 deductible against ordinary income", "$3,000 net capital loss; full $3,000 deductible", "$8,000 loss; $3,000 deductible", "$5,000 gain; fully taxable"]'::jsonb,
 0,
 'Net capital gain/loss = $5,000 LTCG - $8,000 STCL = ($3,000) net capital loss. Individual taxpayers may deduct up to $3,000 of net capital losses against ordinary income per year ($1,500 if married filing separately). The $3,000 net loss is fully deductible this year. Any excess would carry forward.',
 'medium'),

(3, 'Property Transactions: Gains/Losses',
 'Under IRC Section 1250, what type of property is subject to unrecaptured Section 1250 gain rules?',
 '["Personal property used in a trade or business", "Depreciable real property (buildings and structural components)", "Inventory", "Stocks and bonds"]'::jsonb,
 1,
 'Section 1250 applies to depreciable real property (buildings, structural components). Unrecaptured Section 1250 gain represents the amount of gain attributable to straight-line depreciation claimed on real property. This gain is taxed at a maximum rate of 25%, rather than the standard long-term capital gains rate of 15% or 20%.',
 'hard'),

(3, 'Property Transactions: Gains/Losses',
 'A taxpayer sells their primary residence for $600,000. They purchased it 10 years ago for $200,000 and have lived in it as their primary residence for all 10 years. What amount of gain is excluded under Section 121 if the taxpayer is single?',
 '["$0", "$250,000", "$400,000", "$500,000"]'::jsonb,
 1,
 'Under IRC Section 121, a single taxpayer may exclude up to $250,000 of gain from the sale of a primary residence ($500,000 for married filing jointly). The ownership and use tests require the taxpayer to have owned and used the home as a primary residence for at least 2 of the 5 years before the sale. The gain is $400,000, but only $250,000 is excluded. The remaining $150,000 is taxable.',
 'medium'),

-- Like-Kind Exchanges (3 questions)
(3, 'Like-Kind Exchanges',
 'In a Section 1031 exchange, what is "boot"?',
 '["The replacement property received", "Non-like-kind property, cash, or debt relief received in the exchange that triggers gain recognition", "The relinquished property given up", "The qualified intermediary''s fee"]'::jsonb,
 1,
 'Boot is any non-like-kind property received in an exchange, including cash, personal property, and net debt relief. Boot triggers recognition of gain to the extent received. In a Section 1031 exchange, boot is the taxable portion of the transaction — the taxpayer recognizes the lesser of realized gain or boot received.',
 'easy'),

(3, 'Like-Kind Exchanges',
 'A taxpayer completes a deferred Section 1031 exchange using a qualified intermediary. The relinquished property is transferred on March 1. By what date must the replacement property be identified?',
 '["Within 30 days (March 31)", "Within 45 days (April 15)", "Within 180 days (August 28)", "Within one year (March 1 of the following year)"]'::jsonb,
 1,
 'In a deferred exchange, the taxpayer must identify the replacement property within 45 days after transferring the relinquished property. The replacement property must be received within 180 days (or the due date of the tax return, including extensions, whichever is earlier). Both deadlines are strict and cannot be extended.',
 'medium'),

(3, 'Like-Kind Exchanges',
 'A taxpayer exchanges an office building (adjusted basis $300,000, FMV $500,000, subject to a $100,000 mortgage) for a warehouse (FMV $400,000) with no mortgage. The buyer assumes the taxpayer''s mortgage. What is the taxpayer''s recognized gain?',
 '["$0", "$100,000", "$200,000", "$50,000"]'::jsonb,
 1,
 'Realized gain = FMV received ($400,000 + $100,000 debt relief) - basis ($300,000) = $200,000. Boot received = $100,000 (net debt relief, since the taxpayer''s mortgage was assumed without taking on any new debt). Recognized gain = lesser of realized gain ($200,000) or boot ($100,000) = $100,000.',
 'hard'),

-- Individual Taxation: Deductions (5 questions)
(3, 'Individual Taxation: Deductions',
 'Which of the following is an above-the-line deduction (adjustment to gross income)?',
 '["Charitable contributions", "State and local taxes", "Student loan interest", "Mortgage interest"]'::jsonb,
 2,
 'Student loan interest (up to $2,500) is an above-the-line deduction that reduces gross income to arrive at adjusted gross income (AGI). Charitable contributions, state and local taxes, and mortgage interest are below-the-line deductions available only if the taxpayer itemizes. Above-the-line deductions are available regardless of whether the taxpayer itemizes.',
 'easy'),

(3, 'Individual Taxation: Deductions',
 'For 2025, a married couple filing jointly has AGI of $150,000. They paid $12,000 in state and local income taxes, $8,000 in property taxes, and $15,000 in mortgage interest. What is their state and local tax (SALT) deduction?',
 '["$20,000", "$10,000", "$12,000", "$35,000"]'::jsonb,
 1,
 'The Tax Cuts and Jobs Act capped the SALT deduction at $10,000 ($5,000 for married filing separately). The total state/local income taxes ($12,000) plus property taxes ($8,000) = $20,000, but the deduction is limited to $10,000. The mortgage interest deduction of $15,000 is separate and not subject to the SALT cap.',
 'medium'),

(3, 'Individual Taxation: Deductions',
 'A self-employed taxpayer pays $12,000 in health insurance premiums for their family. What portion of this amount is deductible as an above-the-line deduction?',
 '["None — health insurance is never deductible", "100% of the premiums ($12,000), subject to the net profit limitation", "50% of the premiums ($6,000)", "Only the amount exceeding 7.5% of AGI"]'::jsonb,
 1,
 'Self-employed individuals can deduct 100% of health insurance premiums paid for themselves, their spouse, and dependents as an above-the-line deduction. However, the deduction cannot exceed the taxpayer''s net self-employment income. This is more favorable than the 7.5% AGI floor that applies to medical expenses as an itemized deduction.',
 'medium'),

(3, 'Individual Taxation: Deductions',
 'A taxpayer donates stock with a FMV of $20,000 and an adjusted basis of $5,000 to a qualified public charity. The taxpayer has held the stock for 3 years. What is the charitable contribution deduction?',
 '["$5,000 (basis)", "$20,000 (FMV)", "$15,000 (gain only)", "$10,000 (50% of FMV)"]'::jsonb,
 1,
 'Donations of long-term capital gain property (held more than one year) to a qualified public charity are generally deductible at fair market value, subject to a 30% of AGI limitation. The $20,000 FMV is the deduction amount, not the $5,000 basis. The taxpayer avoids paying capital gains tax on the $15,000 appreciation and gets a deduction for the full FMV.',
 'medium'),

(3, 'Individual Taxation: Deductions',
 'The qualified business income (QBI) deduction under Section 199A allows eligible taxpayers to deduct what percentage of qualified business income from a pass-through entity?',
 '["10%", "15%", "20%", "25%"]'::jsonb,
 2,
 'Section 199A allows eligible taxpayers to deduct up to 20% of qualified business income from pass-through entities (sole proprietorships, partnerships, S corporations, trusts, and estates). The deduction is subject to limitations based on taxable income, W-2 wages paid, and the type of business (specified service trades or businesses face additional phase-outs).',
 'easy'),

-- Individual Taxation: Filing/Credits (3 questions)
(3, 'Individual Taxation: Filing/Credits',
 'Which filing status generally provides the most favorable tax rates for an individual taxpayer?',
 '["Single", "Married filing jointly", "Married filing separately", "Head of household"]'::jsonb,
 1,
 'Married filing jointly generally provides the widest tax brackets and the most favorable rates, along with access to the most credits and deductions. Head of household is the next most favorable for qualifying individuals. Married filing separately usually results in the highest tax liability and limits access to several credits.',
 'easy'),

(3, 'Individual Taxation: Filing/Credits',
 'The Earned Income Tax Credit (EITC) is designed to benefit which group of taxpayers?',
 '["High-income taxpayers with capital gains", "Low-to-moderate income working individuals and families", "Retired taxpayers receiving Social Security", "Self-employed taxpayers regardless of income"]'::jsonb,
 1,
 'The EITC is a refundable tax credit designed to supplement the wages of low-to-moderate income workers. The credit amount varies based on filing status, number of qualifying children, and earned income. Because it is refundable, taxpayers can receive the credit even if it exceeds their tax liability.',
 'easy'),

(3, 'Individual Taxation: Filing/Credits',
 'A taxpayer has three qualifying children under age 17. For 2025, what is the maximum child tax credit available (before phase-outs)?',
 '["$2,000", "$3,000", "$6,000", "$4,500"]'::jsonb,
 2,
 'The child tax credit is $2,000 per qualifying child under age 17 (as established by the TCJA). For three qualifying children, the maximum credit is $2,000 x 3 = $6,000 before any phase-out. The credit phases out at $400,000 AGI for married filing jointly and $200,000 for other filers.',
 'medium'),

-- C Corporations (4 questions)
(3, 'C Corporations',
 'When a C corporation distributes property (not cash) to a shareholder as a dividend, how does the corporation determine the amount of the distribution?',
 '["At the property''s adjusted basis", "At the property''s fair market value", "At the lesser of basis or FMV", "At the original cost of the property"]'::jsonb,
 1,
 'When a corporation distributes property as a dividend, the amount of the distribution to the shareholder is the fair market value of the property on the distribution date. Additionally, the corporation recognizes gain as if it sold the property for FMV (but does not recognize loss on non-liquidating distributions of depreciated property).',
 'medium'),

(3, 'C Corporations',
 'A C corporation has current-year earnings and profits (E&P) of $100,000 and accumulated E&P of ($30,000) — a deficit. The corporation distributes $90,000 to its sole shareholder. How is the distribution treated?',
 '["Entirely as a dividend", "$70,000 dividend and $20,000 return of capital", "$90,000 return of capital", "$100,000 dividend"]'::jsonb,
 0,
 'Current E&P is allocated first to distributions. Since current E&P ($100,000) exceeds the distribution ($90,000), the entire $90,000 is treated as a dividend, even though accumulated E&P has a deficit. Current E&P is determined without regard to accumulated E&P deficits when determining the tax treatment of current distributions.',
 'hard'),

(3, 'C Corporations',
 'Which of the following is a requirement for a corporation to be classified as a personal holding company (PHC)?',
 '["More than 50% of the corporation''s stock must be owned by 5 or fewer individuals and at least 60% of its adjusted ordinary gross income must be personal holding company income", "The corporation must have fewer than 100 shareholders", "The corporation must be publicly traded", "The corporation must have no employees"]'::jsonb,
 0,
 'A personal holding company must meet two tests: (1) the stock ownership test — more than 50% of outstanding stock is owned (directly or indirectly) by 5 or fewer individuals at any time during the last half of the tax year, and (2) the income test — at least 60% of adjusted ordinary gross income is PHC income (dividends, interest, rents, royalties, etc.).',
 'hard'),

(3, 'C Corporations',
 'A shareholder transfers property with a basis of $50,000 and FMV of $80,000 to a newly formed corporation in exchange for 100% of the stock. Under Section 351, what is the shareholder''s basis in the stock received?',
 '["$80,000", "$50,000", "$30,000", "$0"]'::jsonb,
 1,
 'Under Section 351, when property is transferred to a corporation in exchange for stock and the transferor controls the corporation (80% or more ownership immediately after), no gain or loss is recognized. The shareholder''s basis in the stock equals the basis of the property transferred ($50,000), preserving the built-in gain for future recognition upon sale of the stock.',
 'medium'),

-- S Corporations (3 questions)
(3, 'S Corporations',
 'Which of the following entities is eligible to be a shareholder in an S corporation?',
 '["A C corporation", "A nonresident alien individual", "A domestic individual who is a U.S. citizen", "A partnership"]'::jsonb,
 2,
 'S corporation shareholders must be U.S. citizens or resident aliens, certain trusts, estates, or tax-exempt organizations. C corporations, partnerships, nonresident aliens, and most LLCs taxed as partnerships are ineligible shareholders. If an ineligible shareholder acquires stock, the S election is automatically terminated.',
 'easy'),

(3, 'S Corporations',
 'An S corporation has accumulated earnings and profits (AE&P) from prior C corporation years. If the S corporation distributes cash in excess of its accumulated adjustments account (AAA), how is the excess treated?',
 '["Always as a return of capital", "As a dividend to the extent of AE&P, then return of capital, then capital gain", "As capital gain", "The distribution is not taxable"]'::jsonb,
 1,
 'For S corporations with AE&P from C corporation years, distributions follow a specific ordering: first from the AAA (tax-free return of S corp income already taxed to shareholders), then from AE&P (taxable as a dividend), then as a return of capital (reducing stock basis), and finally as capital gain (after basis is reduced to zero).',
 'hard'),

(3, 'S Corporations',
 'An S corporation must use which of the following tax years?',
 '["Any fiscal year elected by the corporation", "A calendar year, unless a business purpose for a fiscal year is established", "A fiscal year ending September 30", "The same year as its majority shareholder"]'::jsonb,
 1,
 'S corporations are generally required to use a calendar year (December 31) as their tax year. A fiscal year may be used only if the corporation can establish a business purpose (under Section 444, a deferral period of up to 3 months may be elected with a required payment). This prevents shareholders from deferring income recognition.',
 'medium'),

-- Partnerships (5 questions)
(3, 'Partnerships',
 'A partnership is formed when two individuals contribute property. Under IRC Section 721, what is the tax consequence to the partners?',
 '["Each partner recognizes gain equal to the FMV of the property contributed", "No gain or loss is recognized by the partners on the contribution", "Gain is recognized only if the FMV exceeds the basis by more than $10,000", "Loss is recognized if the basis exceeds the FMV"]'::jsonb,
 1,
 'Section 721 provides that no gain or loss is recognized by a partner or the partnership on the contribution of property to a partnership in exchange for a partnership interest. This is a nonrecognition provision that defers gain by preserving the partner''s basis (outside basis equals basis of property contributed plus any cash contributed).',
 'easy'),

(3, 'Partnerships',
 'How does a partner''s share of partnership liabilities affect their outside basis?',
 '["Liabilities have no effect on basis", "A partner''s share of partnership recourse liabilities increases their outside basis", "Liabilities decrease outside basis", "Only nonrecourse liabilities affect basis"]'::jsonb,
 1,
 'A partner''s share of partnership liabilities (both recourse and nonrecourse) increases their outside basis under Section 752. This is important because it affects the partner''s ability to deduct losses (limited to outside basis) and the tax treatment of distributions. An increase in a partner''s share of liabilities is treated as a cash contribution.',
 'medium'),

(3, 'Partnerships',
 'A partnership has a substantial built-in loss in contributed property. Under Section 704(c), who bears the tax consequences of this built-in loss?',
 '["All partners equally", "Only the contributing partner", "Only the noncontributing partners", "The partnership itself"]'::jsonb,
 1,
 'Section 704(c) requires that built-in gains and losses on contributed property be allocated to the contributing partner. This prevents a contributing partner from shifting pre-contribution gains or losses to other partners. The contributing partner must recognize the built-in loss when the property is sold by the partnership.',
 'hard'),

(3, 'Partnerships',
 'What is a guaranteed payment in a partnership?',
 '["A distribution from partnership profits", "A payment to a partner for services or use of capital determined without regard to partnership income", "A loan from the partnership to a partner", "A capital contribution by a partner"]'::jsonb,
 1,
 'Guaranteed payments are payments to a partner for services rendered or use of capital that are determined without regard to partnership income. They are treated as ordinary income to the receiving partner and are deductible by the partnership (similar to salary or interest payments). They differ from distributive share, which depends on partnership income.',
 'medium'),

(3, 'Partnerships',
 'A partner sells their partnership interest for $200,000. Their outside basis is $120,000, and their share of partnership hot assets (unrealized receivables and inventory) is $30,000. How much of the gain is ordinary income?',
 '["$0", "$30,000", "$80,000", "$50,000"]'::jsonb,
 1,
 'Under Section 751, when a partner sells their interest, the portion of the gain attributable to hot assets (unrealized receivables and substantially appreciated inventory) is treated as ordinary income. The $30,000 allocable to hot assets is ordinary income. The remaining gain ($200,000 - $120,000 - $30,000 = $50,000) is capital gain.',
 'hard'),

-- Tax Procedures (4 questions)
(3, 'Tax Procedures',
 'What is the standard statute of limitations for the IRS to assess additional tax?',
 '["1 year from the filing date", "3 years from the later of the filing date or due date", "5 years from the filing date", "There is no statute of limitations"]'::jsonb,
 1,
 'The general statute of limitations for assessment is 3 years from the later of the date the return was filed or the due date of the return. If the taxpayer omits more than 25% of gross income, the period is extended to 6 years. There is no statute of limitations for fraud or failure to file.',
 'easy'),

(3, 'Tax Procedures',
 'A taxpayer disagrees with the IRS''s proposed assessment after an audit. What is the taxpayer''s first option for administrative appeal?',
 '["File a lawsuit in federal district court", "Request a conference with the IRS Office of Appeals", "File an amended return", "Pay the tax and file a claim for refund"]'::jsonb,
 1,
 'After an IRS examination results in a proposed assessment, the taxpayer can request a conference with the IRS Office of Appeals (now Independent Office of Appeals). This is an administrative appeal that provides an opportunity to resolve the dispute without going to court. The Appeals Office is independent from the examination function.',
 'medium'),

(3, 'Tax Procedures',
 'The accuracy-related penalty under IRC Section 6662 is imposed at what rate?',
 '["10% of the underpayment", "20% of the underpayment", "50% of the underpayment", "75% of the underpayment"]'::jsonb,
 1,
 'The accuracy-related penalty under Section 6662 is 20% of the portion of the underpayment attributable to negligence, disregard of rules, substantial understatement of income tax, substantial valuation misstatement, or other specified causes. The penalty can be avoided if the taxpayer had reasonable cause and acted in good faith.',
 'medium'),

(3, 'Tax Procedures',
 'A taxpayer files a fraudulent return. What penalty applies to the underpayment attributable to fraud?',
 '["20% of the underpayment", "50% of the underpayment", "75% of the underpayment", "100% of the underpayment"]'::jsonb,
 2,
 'The civil fraud penalty under IRC Section 6663 is 75% of the portion of the underpayment attributable to fraud. This is in addition to the tax owed and any interest. The burden of proof for fraud is on the IRS, which must establish fraud by clear and convincing evidence. Criminal penalties (fines and imprisonment) may also apply.',
 'hard'),

-- Estate and Gift Tax (4 questions)
(3, 'Estate and Gift Tax',
 'For 2025, what is the annual gift tax exclusion amount per donee?',
 '["$15,000", "$16,000", "$17,000", "$18,000"]'::jsonb,
 3,
 'The annual gift tax exclusion for 2025 is $18,000 per donee ($36,000 for married couples electing gift splitting). This means a taxpayer can give up to $18,000 to any number of individuals without incurring gift tax or using any of their lifetime exemption. The exclusion applies to present interest gifts only.',
 'easy'),

(3, 'Estate and Gift Tax',
 'Which of the following transfers is subject to gift tax?',
 '["A gift to a qualified charity", "Payment of a grandchild''s tuition directly to the university", "A transfer of $50,000 to a friend with no consideration", "Payment of a child''s medical expenses directly to the hospital"]'::jsonb,
 2,
 'A transfer of $50,000 to a friend exceeds the annual exclusion and is a taxable gift (the excess over $18,000). Charitable gifts are deductible, and direct payments of tuition or medical expenses to the provider are specifically excluded from gift tax under Section 2503(e) regardless of amount. Only the transfer to the friend creates a gift tax event.',
 'medium'),

(3, 'Estate and Gift Tax',
 'A decedent''s gross estate includes which of the following?',
 '["Only assets held in the decedent''s name at death", "Only assets passing through the probate process", "All assets in which the decedent had an interest at death, including life insurance proceeds, jointly held property, and certain transferred property", "Only assets listed in the decedent''s will"]'::jsonb,
 2,
 'The gross estate is broader than probate assets. It includes all property in which the decedent had an interest at death, life insurance proceeds payable to the estate or where the decedent held incidents of ownership, jointly held property, property over which the decedent held a general power of appointment, and certain transfers made within 3 years of death.',
 'medium'),

(3, 'Estate and Gift Tax',
 'A decedent dies in 2025 with a gross estate of $15 million. The unified credit exemption amount for 2025 is $13.61 million. Assuming no deductions, what is the taxable estate?',
 '["$0", "$1,390,000", "$15,000,000", "$13,610,000"]'::jsonb,
 1,
 'The taxable estate = gross estate - deductions - exemption. With no deductions, the estate tax applies to $15,000,000 - $13,610,000 = $1,390,000. The unified credit exemption shelters the first $13.61 million from estate tax. The excess is taxed at the estate tax rate of 40%.',
 'hard'),

-- Professional Ethics in Tax (4 questions)
(3, 'Professional Ethics in Tax',
 'A CPA prepares a tax return and discovers the client has unreported income from a foreign bank account. What is the CPA''s obligation?',
 '["Report the account directly to FINCEN", "Inform the client of the reporting obligation and the consequences of noncompliance, and consider withdrawal if the client refuses to comply", "File the FBAR on behalf of the client without their knowledge", "Ignore the issue since foreign income is not taxable"]'::jsonb,
 1,
 'The CPA must inform the client about the obligation to report foreign bank accounts (FBAR and Form 8938 if applicable) and the potential penalties for noncompliance. The CPA should not file reports without client consent but should consider whether to continue the engagement if the client refuses to comply with legal reporting requirements.',
 'medium'),

(3, 'Professional Ethics in Tax',
 'Under AICPA Statements on Standards for Tax Services, a CPA may recommend a tax return position if:',
 '["The CPA personally agrees with the position, regardless of authority", "There is a realistic possibility of the position being sustained on its merits (generally interpreted as at least a one-in-three likelihood)", "The position will definitely save the client money", "Another CPA has taken the same position on a different return"]'::jsonb,
 1,
 'Under SSTS No. 1, a CPA should not recommend a tax return position unless there is a realistic possibility of it being sustained on its merits. This is generally interpreted as at least a one-in-three (33%) likelihood. If the position does not meet this threshold but has a reasonable basis, it may still be taken if adequately disclosed.',
 'hard'),

(3, 'Professional Ethics in Tax',
 'A CPA learns that a client provided incorrect information on a prior-year return that is still open under the statute of limitations. What should the CPA do?',
 '["Amend the return without informing the client", "Promptly inform the client of the error, its potential consequences, and recommend corrective action", "Report the client to the IRS", "Do nothing since the return has already been filed"]'::jsonb,
 1,
 'Under SSTS No. 6, when a CPA becomes aware of an error on a filed return, they must promptly inform the client and recommend appropriate corrective action (such as filing an amended return). The CPA cannot amend without client authorization and is not required to notify the IRS. However, the CPA should consider the implications for the current engagement.',
 'medium'),

(3, 'Professional Ethics in Tax',
 'When may a CPA rely on information furnished by a client without verification for tax return preparation?',
 '["Never — all information must be independently verified", "When the information appears reasonable and consistent, and the CPA has no reason to doubt its accuracy", "Only when the client provides written documentation for every item", "Only for items under $1,000"]'::jsonb,
 1,
 'Under SSTS No. 3, a CPA is not required to examine or verify all supporting data. The CPA may rely on information provided by the client if it appears reasonable and there is no reason to believe it is incorrect or incomplete. However, the CPA should make reasonable inquiries if information appears questionable or inconsistent.',
 'easy');
